```typescript
// ThreadSpec - Declares all expectations (zero runtime cost)
import 'reflect-metadata';

interface ThreadSpecOptions {
  threads: string[];
  expects?: {
    params?: Record<string, string | TypeExpectation>;
    timing?: { min: number; max: number; unit?: 'ms' | 's' };
    memory?: { max: number; unit?: 'MB' | 'KB' };
    throughput?: { min: number; unit?: string };
  };
  produces?: {
    returns?: string | TypeExpectation;
    shape?: Record<string, any>;
    size?: { min?: number; max?: number; unit?: string };
  };
  invariants?: string[];  // Conditions that must always be true
  sideEffects?: string[];  // Expected side effects
}

interface TypeExpectation {
  type: string;
  nullable?: boolean;
  range?: [number, number];
  pattern?: string;
  enum?: any[];
}

export function ThreadSpec(spec: ThreadSpecOptions) {
  return function (target: any, propertyKey: string, descriptor?: PropertyDescriptor) {
    // Store complete specification as metadata
    Reflect.defineMetadata('threadspec', spec, target, propertyKey);

    // Also store at class level for discovery
    const classSpecs = Reflect.getMetadata('class:threadspecs', target.constructor) || new Map();
    classSpecs.set(propertyKey, spec);
    Reflect.defineMetadata('class:threadspecs', classSpecs, target.constructor);

    // Add to global registry for analysis tools
    ThreadRegistry.register(`${target.constructor.name}.${propertyKey}`, spec);
  };
}

// Usage Example
class DataService {
  @ThreadSpec({
    threads: ['DATA_FLOW', 'CACHE'],
    expects: {
      params: {
        userId: { type: 'string', pattern: '^[0-9a-f]{8}' },
        options: { type: 'object', nullable: true }
      },
      timing: { min: 10, max: 100, unit: 'ms' },
      memory: { max: 50, unit: 'MB' }
    },
    produces: {
      returns: { type: 'User', nullable: true },
      size: { min: 100, max: 10000, unit: 'bytes' }
    },
    invariants: [
      'Cache must be checked before database',
      'User ID must be validated'
    ],
    sideEffects: [
      'Updates cache on miss',
      'Logs access for audit'
    ]
  })
  async getUser(userId: string, options?: any): Promise<User | null> {
    // Implementation
  }
}
