```typescript
// ThreadLog - Captures reality and performs simple delta detection
import { performance } from 'perf_hooks';

export function ThreadLog(...threads: string[]) {
  return function (target: any, propertyKey: string, descriptor: PropertyDescriptor) {
    const originalMethod = descriptor.value;

    descriptor.value = async function (...args: any[]) {
      const config = ThreadConfig.get();
      if (!config.enabled) return originalMethod.apply(this, args);

      // Check which threads are active
      const activeThreads = threads.filter(t => config.isThreadActive(t));
      if (activeThreads.length === 0) return originalMethod.apply(this, args);

      // Get expectations from ThreadSpec
      const spec = Reflect.getMetadata('threadspec', target, propertyKey);
      const context = `${target.constructor.name}.${propertyKey}`;
      const startTime = performance.now();
      const startMemory = process.memoryUsage().heapUsed;

      // Log entry
      const entryLog = {
        type: 'entry',
        context,
        threads: activeThreads,
        timestamp: Date.now(),
        args: args.map(a => ({ 
          type: typeof a, 
          shape: getShape(a),
          size: getSize(a)
        })),
        expectations: spec?.expects
      };

      ThreadLogger.log(entryLog);

      // Simple input validation against spec
      if (spec?.expects?.params) {
        const paramDeltas = validateParams(args, spec.expects.params);
        if (paramDeltas.length > 0) {
          ThreadLogger.log({
            type: 'delta',
            subtype: 'input-mismatch',
            context,
            deltas: paramDeltas,
            severity: 'warning'
          });
        }
      }

      try {
        const result = await originalMethod.apply(this, args);
        const duration = performance.now() - startTime;
        const memoryDelta = process.memoryUsage().heapUsed - startMemory;

        // Log exit with actuals
        const exitLog = {
          type: 'exit',
          context,
          threads: activeThreads,
          duration,
          memoryDelta,
          result: {
            type: typeof result,
            shape: getShape(result),
            size: getSize(result)
          },
          timestamp: Date.now()
        };

        ThreadLogger.log(exitLog);

        // Simple delta detection (inline, cheap)
        const deltas = [];

        // Timing delta
        if (spec?.expects?.timing) {
          const { min, max } = spec.expects.timing;
          if (duration < min || duration > max) {
            deltas.push({
              type: 'timing',
              expected: `${min}-${max}ms`,
              actual: `${duration.toFixed(2)}ms`,
              deviation: duration > max ? 'slow' : 'fast',
              percentage: ((duration - max) / max * 100).toFixed(1)
            });
          }
        }

        // Memory delta
        if (spec?.expects?.memory) {
          const maxBytes = spec.expects.memory.max * (spec.expects.memory.unit === 'MB' ? 1024*1024 : 1024);
          if (memoryDelta > maxBytes) {
            deltas.push({
              type: 'memory',
              expected: `${spec.expects.memory.max}${spec.expects.memory.unit}`,
              actual: `${(memoryDelta / 1024 / 1024).toFixed(2)}MB`,
              deviation: 'excessive'
            });
          }
        }

        // Output shape delta
        if (spec?.produces?.shape) {
          const shapeDeltas = validateShape(result, spec.produces.shape);
          if (shapeDeltas.length > 0) {
            deltas.push({
              type: 'shape',
              mismatches: shapeDeltas
            });
          }
        }

        // Log simple deltas immediately
        if (deltas.length > 0) {
          ThreadLogger.log({
            type: 'delta',
            subtype: 'simple',
            context,
            threads: activeThreads,
            deltas,
            severity: deltas.some(d => d.deviation === 'slow' || d.deviation === 'excessive') ? 'warning' : 'info'
          });
        }

        return result;

      } catch (error) {
        const duration = performance.now() - startTime;

        ThreadLogger.log({
          type: 'error',
          context,
          threads: [...activeThreads, 'ERROR_RECOVERY'],
          error: {
            message: error.message,
            stack: error.stack,
            type: error.constructor.name
          },
          duration,
          timestamp: Date.now()
        });

        // Check if error was expected
        if (spec?.sideEffects) {
          const expectedError = spec.sideEffects.some(se => 
            se.includes('throw') || se.includes('error')
          );
          if (!expectedError) {
            ThreadLogger.log({
              type: 'delta',
              subtype: 'unexpected-error',
              context,
              severity: 'error'
            });
          }
        }

        throw error;
      }
    };

    return descriptor;
  };
}
