# Thread Control Center API

## Core Class

```typescript
export class ThreadControlCenter {
  private static instance: ThreadControlCenter;
  private config: ThreadConfig;
  private statusBarItem: vscode.StatusBarItem;
  private activeSession?: ThreadSession;

  // Singleton access
  static getInstance(): ThreadControlCenter;

  // Configuration management
  loadConfig(path?: string): Promise<void>;
  updateConfig(updates: Partial<ThreadConfig>): Promise<void>;

  // Thread control
  enableThreads(threads: string[]): void;
  disableThreads(threads: string[]): void;
  toggleThread(thread: string): void;
  setMode(mode: 'disabled' | 'development' | 'debugging' | 'learning'): void;

  // Session management
  startSession(name?: string): ThreadSession;
  endSession(): Promise<SessionSummary>;
  pauseSession(): void;
  resumeSession(): void;

  // Real-time monitoring
  attachToLog(callback: (entry: LogEntry) => void): Disposable;
  getActiveThreads(): string[];
  getSessionMetrics(): SessionMetrics;

  // Quick actions
  quickEnable(): Promise<void>;  // Shows quick pick for thread selection
  quickAnalyze(): Promise<void>; // Runs analysis on current logs
  clearLogs(): Promise<void>;

  // UI Integration
  showStatusBar(): void;
  hideStatusBar(): void;
  showControlPanel(): Promise<void>;
}
```

## VSCode Commands

```typescript
// Register commands
export function registerThreadingCommands(context: vscode.ExtensionContext) {
  const control = ThreadControlCenter.getInstance();

  // Quick toggle
  context.subscriptions.push(
    vscode.commands.registerCommand('threading.toggle', () => {
      control.setMode(control.getMode() === 'disabled' ? 'development' : 'disabled');
    })
  );

  // Select threads
  context.subscriptions.push(
    vscode.commands.registerCommand('threading.selectThreads', async () => {
      await control.quickEnable();
    })
  );

  // Analyze current
  context.subscriptions.push(
    vscode.commands.registerCommand('threading.analyze', async () => {
      await control.quickAnalyze();
    })
  );

  // Show panel
  context.subscriptions.push(
    vscode.commands.registerCommand('threading.showPanel', async () => {
      await control.showControlPanel();
    })
  );
}
```

## Status Bar Integration

The status bar shows current threading state:
- Red circle: Threading Disabled
- Yellow circle: Threading Dev Mode with active threads
- Green circle: Threading Debug Mode (all threads)
- Blue circle: Threading Learning Mode

Click to toggle, right-click for menu options.

# ThreadAnalyzer - Asynchronous Analysis Engine

## Architecture

```typescript
export class ThreadAnalyzer {
  private logStream: LogStream;
  private patternDetectors: PatternDetector[];
  private learningEngine: LearningEngine;

  constructor(config: AnalyzerConfig) {
    this.logStream = new LogStream(config.logPath);
    this.patternDetectors = [
      new PerformanceDegradationDetector(),
      new ErrorClusterDetector(),
      new ThreadDeadlockDetector(),
      new CacheMissPatternDetector(),
      new MemoryLeakDetector()
    ];
    this.learningEngine = new LearningEngine();
  }

  // Start background analysis
  startAnalysis(): void {
    this.logStream.on('batch', async (entries) => {
      // Run pattern detection
      const patterns = await this.detectPatterns(entries);

      // Generate insights
      const insights = await this.generateInsights(patterns);

      // Create learning items if significant
      if (insights.significance > 0.7) {
        await this.createLearningItem(insights);
      }

      // Notify if critical
      if (insights.severity === 'critical') {
        await this.notifyOperator(insights);
      }
    });
  }
}
```

## Pattern Detectors

### Performance Degradation
```typescript
class PerformanceDegradationDetector {
  detect(entries: LogEntry[]): Pattern[] {
    // Group by context
    const contextGroups = groupBy(entries, 'context');
    const patterns = [];

    for (const [context, contextEntries] of contextGroups) {
      // Get timing deltas over time
      const timingDeltas = contextEntries
        .filter(e => e.type === 'delta' && e.deltas.some(d => d.type === 'timing'))
        .map(e => ({
          timestamp: e.timestamp,
          expected: parseExpectedTime(e.deltas[0].expected),
          actual: parseActualTime(e.deltas[0].actual)
        }));

      // Check for degradation trend
      if (timingDeltas.length > 5) {
        const trend = calculateTrend(timingDeltas.map(d => d.actual));

        if (trend.slope > 0.1) {  // Getting slower
          patterns.push({
            type: 'performance-degradation',
            context,
            confidence: trend.r2,  // R-squared value
            evidence: timingDeltas,
            description: `Performance degrading at ${trend.slope.toFixed(2)}ms per execution`,
            hypothesis: this.generateHypothesis(context, trend)
          });
        }
      }
    }

    return patterns;
  }
}
```

