class LearningEngine {
  async createLearningItem(insights: Insights): Promise<KnowledgeItem> {
    const item: KnowledgeItem = {
      id: uuid(),
      type: 'learning',
      scope: 'project',
      title: this.generateTitle(insights),
      body: this.generateLearningBody(insights),
      tags: this.extractTags(insights),
      metadata: {
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        source: 'thread-analyzer',
        confidence: insights.confidence,
        evidence: {
          sampleCount: insights.patterns.length,
          timeRange: insights.timeRange
        }
      }
    };

    // Save to knowledge base
    await KnowledgeBase.add(item);

    return item;
  }
}
